opts: ["0 — Lỗi khi sao chép hoặc phần giao nhau", "1 — Sao chép đúng"],
def: 1,
imagem: true,
},
];

const DOM_MAX = {
"Định hướng thời gian": 5,
"Định hướng không gian": 5,
Registro: 3,
"Chú ý và Tính toán": 5,
Evocacao: 3,
Nomeacao: 2,
Repeticao: 1,
Compreensao: 3,
Escrita: 1,
Leitura: 1,
Praxia: 1,
};

// ---- ESTADO ----
let cronoSegundos = 0,
cronoAtivo = false,
cronoIntervalo = null,
cronoFinal = null;
let chartBarra = null,
chartRadar = null;

// ---- HELPERS ----
function formatarTempo(s) {
return String(Math.floor(s / 60)).padStart(2, "0") + ":" + String(s % 60).padStart(2, "0");
}

function getCorPorPct(pct) {
if (pct === 100) return "#16a34a";
if (pct >= 50) return "#1A3E74";
return "#E11D48";
}

// ---- CRONOMETRO ----
const btnCrono = document.getElementById("btnCrono");
const btnCronoReset = document.getElementById("btnCronoReset");
const displayCrono = document.getElementById("cronoDisplay");

function atualizarDisplayCrono() {
displayCrono.textContent = formatarTempo(cronoSegundos);
}

function iniciarCrono() {
if (!cronoIntervalo) {
cronoAtivo = true;
cronoIntervalo = setInterval(function () {
cronoSegundos++;
atualizarDisplayCrono();
}, 1000);
btnCrono.textContent = "Pausar";
btnCrono.style.background = "#FEF2F2";
btnCrono.style.color = "#E11D48";
btnCrono.style.border = "1px solid #FECACA";
btnCrono.style.boxShadow = "none";
btnCronoReset.style.display = "block";
}
}

function pausarCrono() {
if (cronoIntervalo) {
clearInterval(cronoIntervalo);
cronoIntervalo = null;
cronoAtivo = false;
btnCrono.textContent = "Retomar";
btnCrono.style.background = "#1A3E74";
btnCrono.style.color = "white";
btnCrono.style.border = "none";
btnCrono.style.boxShadow = "0 4px 10px rgba(26,62,116,0.3)";
}
}

function retomarCrono() {
if (!cronoIntervalo) {
iniciarCrono();
}
}

function resetCrono() {
clearInterval(cronoIntervalo);
cronoIntervalo = null;
cronoAtivo = false;
cronoSegundos = 0;
atualizarDisplayCrono();
btnCrono.textContent = "Bắt đầu bấm giờ";
btnCrono.style.background = "#1A3E74";
btnCrono.style.color = "white";
btnCrono.style.border = "none";
btnCrono.style.boxShadow = "0 4px 10px rgba(26,62,116,0.3)";
btnCronoReset.style.display = "none";
}

btnCrono.addEventListener("click", function () {
if (btnCrono.textContent === "Bắt đầu bấm giờ") {
iniciarCrono();
} else if (btnCrono.textContent === "Pausar") {
pausarCrono();
} else {
retomarCrono();
}
});

btnCronoReset.addEventListener("click", resetCrono);

// ---- DADOS DO PACIENTE ----
const btnToggleDados = document.getElementById("btnToggleDados");
const dadosBody = document.getElementById("dadosBody");
const dadosChevron = document.getElementById("dadosChevron");
const dadosSubtitle = document.getElementById("dadosSubtitle");

function toggleDados() {
const isOpen = dadosBody.classList.contains("open");
if (isOpen) {
dadosBody.classList.remove("open");
dadosChevron.style.transform = "rotate(0deg)";
dadosSubtitle.textContent = "Điền để đưa vào báo cáo PDF";
btnToggleDados.style.background = "white";
} else {
dadosBody.classList.add("open");
dadosChevron.style.transform = "rotate(180deg)";
dadosSubtitle.textContent = "Ocultar";
btnToggleDados.style.background = "#EFF6FF";
}
}

btnToggleDados.addEventListener("click", toggleDados);

// Data default = hoje
document.getElementById("pacData").value = new Date().toISOString().split("T")[0];

// ---- RENDERIZAR ITENS ----
function renderizarItens() {
const container = document.getElementById("itensMEEM");
container.innerHTML = "";
ITENS_MEEM.forEach(function (item) {
const div = document.createElement("div");
div.className = "item-card";
var imagemHtml = "";
if (item.imagem) {
imagemHtml = '<div style="text-align:center;margin-bottom:12px;"><img src="/pentagono-calculadoras-de-enfermagem.webp" alt="Hình ngũ giác đan xen" style="max-height:90px;border-radius:8px;border:1px solid #E2E8F0;" width="233" height="147"></div>';
}
var optsHtml = "";
item.opts.forEach(function (op, i) {
optsHtml += '<option value="' + i + '"' + (i === item.def ? " selected" : "") + ">" + op + "</option>";
});
div.innerHTML = '<div style="display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:8px;">' + '<label for="' + item.id + '" style="font-size:13px;font-weight:700;color:#1E293B;line-height:1.3;">' + item.label + "</label>" + '<span id="badge_' + item.id + '" class="item-badge">' + item.def + "/" + item.max + "</span>" + "</div>" + '<p style="font-size:12px;color:#64748B;margin-bottom:12px;line-height:1.6;">' + item.desc + "</p>" + imagemHtml + '<select id="' + item.id + '" class="item-select" data-max="' + item.max + '">' + optsHtml + "</select>" + '<div class="mini-bar-wrap"><div id="bar_' + item.id + '" class="mini-bar-fill" style="width:' + (item.def / item.max) * 100 + '%;background:#16a34a;"></div></div>';
container.appendChild(div);

// Add change listener
document.getElementById(item.id).addEventListener("change", function () {
atualizarItem(item.id, item.max);
});
});
}

function atualizarItem(id, max) {
var el = document.getElementById(id);
var val = parseInt(el.value) || 0;
var pct = (val / max) * 100;
var cor = getCorPorPct(Math.round(pct));
document.getElementById("bar_" + id).style.width = pct + "%";
document.getElementById("bar_" + id).style.background = cor;
document.getElementById("badge_" + id).textContent = val + "/" + max;
atualizarProgresso();
}

function atualizarProgresso() {
var soma = 0;
ITENS_MEEM.forEach(function (i) {
var v = parseInt(document.getElementById(i.id).value) || 0;
soma += v;
});
var pct = Math.round((soma / 30) * 100);
var cor = "#1A3E74";
if (pct >= 80) cor = "#16a34a";
else if (pct >= 60) cor = "#D97706";
else if (pct >= 40) cor = "#1A3E74";
else cor = "#E11D48";

document.getElementById("progressoFill").style.width = pct + "%";
document.getElementById("progressoFill").style.background = "linear-gradient(90deg, " + cor + ", " + cor + ")";
document.getElementById("progressoTexto").textContent = soma + " / 30 điểm";
document.getElementById("progressoPct").textContent = pct + "%";
document.getElementById("progressoPct").style.color = cor;
}

// ---- CARREGAR SCRIPTS EXTERNOS ----
function carregarScript(src) {
return new Promise(function (resolve, reject) {
var s = document.createElement("script");
s.src = src;
s.crossOrigin = "anonymous";
s.onload = resolve;
s.onerror = reject;
document.head.appendChild(s);
});
}

var chartJSPronto = false;
var jsPDFPronto = false;

function garantirChartJS() {
if (chartJSPronto && typeof Chart !== "undefined") return Promise.resolve();
return carregarScript("https://cdn.jsdelivr.net/npm/chart.js@4.4.3/dist/chart.umd.min.js").then(function () {
chartJSPronto = true;
});
}

function garantirJSPDF() {
if (jsPDFPronto && typeof window.jspdf !== "undefined") return Promise.resolve();
return carregarScript("https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js")
.then(function () {
return carregarScript("https://cdnjs.cloudflare.com/ajax/libs/jspdf-autotable/3.8.2/jspdf.plugin.autotable.min.js");
})
.then(function () {
jsPDFPronto = true;
});
}
function calcularMEEM() {
// Parar cronometro
if (cronoIntervalo) {
clearInterval(cronoIntervalo);
cronoIntervalo = null;
cronoAtivo = false;
btnCrono.textContent = "Retomar";
btnCrono.style.background = "#1A3E74";
btnCrono.style.color = "white";
}
cronoFinal = cronoSegundos;

var soma = 0;
var valores = {};
ITENS_MEEM.forEach(function (i) {
var v = parseInt(document.getElementById(i.id).value) || 0;
soma += v;
valores[i.id] = v;
});

var esc = document.getElementById("escolaridade").value;
var corte = esc === "analfabeto" ? 20 : esc === "baixa" ? 24 : 28;
var descEsc = esc === "analfabeto" ? "analfabetos" : esc === "baixa" ? "1 đến 11 năm học" : "trên 11 năm học";
var alterado = soma < corte;

// Score
document.getElementById("scoreValor").textContent = soma;
var pill = document.getElementById("statusPill");
if (alterado) {
pill.textContent = "Khả năng suy giảm nhận thức";
pill.style.background = "#E11D48";
} else {
pill.textContent = "Trong phạm vi mong đợi";
pill.style.background = "#16a34a";
}

document.getElementById("resultadoMensagem").innerHTML = alterado ? "Điểm số <strong>" + soma + " điểm</strong>, dưới ngưỡng <strong>" + corte + " điểm</strong> cho " + descEsc + ". Este resultado sugere a necessidade de avaliacao medica e neuropsicologica mais aprofundada." : "Điểm số <strong>" + soma + " điểm</strong>, trong hoặc trên mức mong đợi <strong>" + corte + " điểm</strong> cho " + descEsc + ".";

var tempoEl = document.getElementById("tempoRegistrado");
if (cronoFinal > 0) {
tempoEl.textContent = "Thời gian áp dụng: " + formatarTempo(cronoFinal);
tempoEl.style.display = "block";
}

// Dados por dominio
var domNames = ["Định hướng thời gian", "Định hướng không gian", "Registro", "Chú ý và Tính toán", "Evocacao", "Nomeacao", "Repeticao", "Compreensao", "Escrita", "Leitura", "Praxia"];
var domIds = ITENS_MEEM.map(function (i) {
return i.id;
});
var domVals = domIds.map(function (id) {
return parseInt(document.getElementById(id).value) || 0;
});
var domMaxArr = ITENS_MEEM.map(function (i) {
return i.max;
});
var domPct = domVals.map(function (v, i) {
return Math.round((v / domMaxArr[i]) * 100);
});

// Tabela
var tbody = document.getElementById("tabelaDominios");
tbody.innerHTML = "";
domNames.forEach(function (nome, i) {
var pct = domPct[i];
var cor = getCorPorPct(pct);
var tr = document.createElement("tr");
tr.innerHTML = "<td>" + nome + "</td>" + '<td style="text-align:center;font-weight:700;color:' + cor + ';">' + domVals[i] + "</td>" + '<td style="text-align:center;color:#94A3B8;">' + domMaxArr[i] + "</td>" + "<td>" + '<div style="display:flex;align-items:center;gap:8px;">' + '<div style="flex:1;max-width:100px;height:6px;background:#E2E8F0;border-radius:4px;overflow:hidden;">' + '<div style="width:' + pct + "%;height:100%;background:" + cor + ';border-radius:4px;"></div>' + "</div>" + '<span style="font-size:12px;font-weight:700;color:' + cor + ';">' + pct + "%</span>" + "</div>" + "</td>";
tbody.appendChild(tr);
});

document.getElementById("totalTd").textContent = soma;
document.getElementById("corteTd").innerHTML = '<span style="font-size:12px;font-weight:700;background:' + (alterado ? "#FEF2F2" : "#F0FDF4") + ";color:" + (alterado ? "#E11D48" : "#16a34a") + ';padding:3px 12px;border-radius:20px;">Ngưỡng: ' + corte + " điểm</span>";

// Mostrar resultado
var secao = document.getElementById("resultado-section");
secao.style.display = "block";
setTimeout(function () {
secao.classList.add("visible");
secao.scrollIntoView({ behavior: "auto", block: "start" });
}, 80);

// Renderizar graficos
garantirChartJS().then(function () {
renderizarGraficos(domNames, domVals, domMaxArr, domPct);
});

// Haptic
if (navigator.vibrate) navigator.vibrate(200);
}

function renderizarGraficos(domNames, domVals, domMaxArr, domPct) {
// Grafico de Barras
var ctxB = document.getElementById("graficoBarra").getContext("2d");
if (chartBarra) chartBarra.destroy();
chartBarra = new Chart(ctxB, {
type: "bar",
data: {
labels: domNames.map(function (n) {
return n.length > 12 ? n.slice(0, 12) + "..." : n;
}),
datasets: [
{
label: "Maximo",
data: domMaxArr,
backgroundColor: "#E2E8F0",
borderRadius: 4,
order: 2,
},
{
label: "Obtido",
data: domVals,
backgroundColor: domPct.map(function (p) {
return getCorPorPct(p);
}),
borderRadius: 4,
order: 1,
},
],
},
options: {
responsive: true,
maintainAspectRatio: false,
plugins: { legend: { labels: { font: { size: 11 } } } },
scales: {
x: {
ticks: { font: { size: 9 }, maxRotation: 40 },
grid: { color: "#F1F5F9" },
},
y: {
beginAtZero: true,
ticks: { font: { size: 9 } },
grid: { color: "#F1F5F9" },
},
},
},
});

// Grafico Radar
var ctxR = document.getElementById("graficoRadar").getContext("2d");
if (chartRadar) chartRadar.destroy();
chartRadar = new Chart(ctxR, {
type: "radar",
data: {
labels: domNames.map(function (n) {
return n.length > 14 ? n.slice(0, 14) + "..." : n;
}),
datasets: [
{
label: "Đạt được (%)",
data: domPct,
backgroundColor: "rgba(26,62,116,0.2)",
